import React, { useState, useEffect, useCallback } from 'react';
import api from './api';

// ── STYLES ────────────────────────────────────────────────────────────────────
const G = {
  bg:       '#0A0A0A',
  card:     '#111111',
  card2:    '#181818',
  border:   '#1E1E1E',
  border2:  '#252525',
  green:    '#22C55E',
  greenDark:'#16A34A',
  greenBg:  '#052E1C',
  greenBdr: '#166534',
  text:     '#EEEEEE',
  text2:    '#888888',
  text3:    '#444444',
  red:      '#EF4444',
  amber:    '#F59E0B',
  purple:   '#818CF8',
};

const css = {
  app: { minHeight:'100vh', background:G.bg, color:G.text, fontFamily:"'Inter',sans-serif", fontSize:14 },
  // Layout
  center: { display:'flex', alignItems:'center', justifyContent:'center', minHeight:'100vh', padding:16 },
  col:    { display:'flex', flexDirection:'column', gap:12 },
  row:    { display:'flex', alignItems:'center', gap:8 },
  // Cards
  card:   { background:G.card, border:`1px solid ${G.border}`, borderRadius:16, padding:20 },
  card2:  { background:G.card2, border:`1px solid ${G.border2}`, borderRadius:12, padding:16 },
  // Auth form
  authWrap: { width:'100%', maxWidth:400 },
  brand:    { textAlign:'center', marginBottom:32 },
  brandIcon:{ width:72, height:72, borderRadius:20, background:G.greenBg, display:'flex', alignItems:'center', justifyContent:'center', fontSize:32, margin:'0 auto 16px', border:`1px solid ${G.greenBdr}` },
  brandName:{ fontSize:32, fontWeight:900, color:G.green, letterSpacing:0.5 },
  brandSub: { fontSize:13, color:G.text3, marginTop:6 },
  formTitle:{ fontSize:22, fontWeight:800, color:G.text, marginBottom:20 },
  label:    { fontSize:11, fontWeight:700, color:G.text3, textTransform:'uppercase', letterSpacing:0.8, marginBottom:6, display:'block' },
  input:    { width:'100%', background:G.card2, border:`1px solid ${G.border2}`, borderRadius:10, padding:'13px 14px', fontSize:15, color:G.text, outline:'none', boxSizing:'border-box', transition:'border-color 0.2s' },
  btn:      { width:'100%', background:G.greenDark, color:'#fff', border:'none', borderRadius:10, padding:'15px 20px', fontSize:16, fontWeight:700, cursor:'pointer', transition:'opacity 0.2s' },
  btnSm:    { background:G.greenDark, color:'#fff', border:'none', borderRadius:8, padding:'10px 18px', fontSize:13, fontWeight:600, cursor:'pointer' },
  btnGhost: { background:'transparent', color:G.green, border:`1px solid ${G.border}`, borderRadius:10, padding:'13px 20px', fontSize:14, fontWeight:600, cursor:'pointer', width:'100%' },
  link:     { color:G.green, cursor:'pointer', fontWeight:600 },
  linkText: { fontSize:13, color:G.text3, textAlign:'center' },
  err:      { background:'#200A0A', border:'1px solid #450A0A', borderRadius:8, padding:'10px 14px', fontSize:13, color:G.red },
  ok:       { background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:8, padding:'10px 14px', fontSize:13, color:G.green },
  // Nav
  nav:      { background:'#0F0F0F', borderBottom:`1px solid ${G.border}`, padding:'0 20px', display:'flex', alignItems:'center', justifyContent:'space-between', height:56, position:'sticky', top:0, zIndex:100 },
  navBrand: { fontSize:20, fontWeight:900, color:G.green },
  navRight: { display:'flex', alignItems:'center', gap:12 },
  // Bottom tab bar
  tabBar:   { position:'fixed', bottom:0, left:0, right:0, background:'#0F0F0F', borderTop:`1px solid ${G.border}`, display:'flex', zIndex:100 },
  tabItem:  { flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'10px 0', cursor:'pointer', transition:'color 0.2s', fontSize:10, fontWeight:600, gap:4 },
  // Page
  page:     { maxWidth:480, margin:'0 auto', padding:'20px 16px 90px' },
  pageTitle:{ fontSize:26, fontWeight:800, color:G.text, marginBottom:20 },
  sectionLabel:{ fontSize:11, fontWeight:700, color:G.text3, textTransform:'uppercase', letterSpacing:0.8, marginBottom:10, display:'block' },
  // Status badges
  badge:    { borderRadius:20, padding:'3px 10px', fontSize:10, fontWeight:700, display:'inline-block' },
  // OTP input row
  otpRow:   { display:'flex', gap:8 },
  otpInput: { flex:1, background:G.card2, border:`1px solid ${G.border2}`, borderRadius:10, padding:'13px 14px', fontSize:15, color:G.text, outline:'none', boxSizing:'border-box' },
  otpBtn:   { whiteSpace:'nowrap', background:G.greenDark, color:'#fff', border:'none', borderRadius:10, padding:'0 16px', fontSize:13, fontWeight:600, cursor:'pointer', minWidth:100 },
};

const STATUS_STYLE = {
  pending_payment: { bg:'#2D1F00', color:G.amber,  label:'Awaiting payment' },
  queued:          { bg:'#1A1040', color:G.purple, label:'In queue' },
  printing:        { bg:G.greenBg, color:G.green,  label:'Printing' },
  ready:           { bg:G.greenBg, color:G.green,  label:'Ready for pickup' },
  collected:       { bg:'#1A1A1A', color:G.text3,  label:'Collected' },
  cancelled:       { bg:'#200A0A', color:G.red,    label:'Cancelled' },
  failed:          { bg:'#200A0A', color:G.red,    label:'Failed' },
};

// ── HELPER COMPONENTS ─────────────────────────────────────────────────────────
function Spinner() {
  return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', padding:40 }}>
      <div style={{ width:32, height:32, border:`3px solid ${G.border}`, borderTop:`3px solid ${G.green}`, borderRadius:'50%', animation:'spin 0.8s linear infinite' }}/>
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

function Alert({ msg, type='error' }) {
  if (!msg) return null;
  return <div style={type==='error' ? css.err : css.ok}>{msg}</div>;
}

function TabBar({ active, onNav }) {
  const tabs = [
    { id:'home',    icon:'🏠', label:'Home' },
    { id:'jobs',    icon:'📄', label:'My Jobs' },
    { id:'shops',   icon:'📍', label:'Shops' },
    { id:'profile', icon:'👤', label:'Profile' },
  ];
  return (
    <div style={css.tabBar}>
      {tabs.map(t => (
        <div key={t.id} style={{ ...css.tabItem, color: active===t.id ? G.green : G.text3 }}
          onClick={() => onNav(t.id)}>
          <span style={{ fontSize:20 }}>{t.icon}</span>
          <span>{t.label}</span>
        </div>
      ))}
    </div>
  );
}

// ── SEND OTP BUTTON ────────────────────────────────────────────────────────────
function OTPSender({ phone, onSent }) {
  const [loading, setLoading] = useState(false);
  const [timer,   setTimer]   = useState(0);
  const [msg,     setMsg]     = useState('');

  const send = async () => {
    if (!phone || phone.length !== 10) { setMsg('Enter a valid 10-digit phone number first'); return; }
    setLoading(true); setMsg('');
    try {
      await api.post('/auth/send-otp/', { phone });
      setMsg('OTP sent! Check your phone (or terminal in dev mode)');
      setTimer(60);
      if (onSent) onSent();
      const iv = setInterval(() => setTimer(t => { if(t<=1){clearInterval(iv);return 0;} return t-1; }), 1000);
    } catch(e) {
      setMsg(e.response?.data?.error || 'Failed to send OTP');
    } finally { setLoading(false); }
  };

  return (
    <div style={css.col}>
      <div style={css.otpRow}>
        <button style={css.otpBtn} onClick={send} disabled={loading || timer>0}>
          {loading ? '...' : timer>0 ? `Resend (${timer}s)` : 'Send OTP'}
        </button>
      </div>
      {msg && <Alert msg={msg} type={msg.includes('sent') ? 'ok' : 'error'}/>}
    </div>
  );
}

// ── LOGIN SCREEN ──────────────────────────────────────────────────────────────
function LoginScreen({ onLogin, onGoRegister }) {
  const [phone,    setPhone]    = useState('');
  const [password, setPassword] = useState('');
  const [otp,      setOtp]      = useState('');
  const [err,      setErr]      = useState('');
  const [loading,  setLoading]  = useState(false);
  const [otpSent,  setOtpSent]  = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (!phone || !password || !otp) { setErr('All fields including OTP are required'); return; }
    setLoading(true); setErr('');
    try {
      const { data } = await api.post('/auth/login/', { phone, password, otp });
      localStorage.setItem('token', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      onLogin(data.user);
    } catch(e) {
      setErr(e.response?.data?.error || 'Login failed');
    } finally { setLoading(false); }
  };

  return (
    <div style={css.center}>
      <div style={css.authWrap}>
        <div style={css.brand}>
          <div style={css.brandIcon}>🖨️</div>
          <div style={css.brandName}>PrintShop</div>
          <div style={css.brandSub}>Print anywhere. Pay once. Collect on the way.</div>
        </div>
        <div style={css.card}>
          <div style={css.formTitle}>Sign in</div>
          <form onSubmit={submit} style={css.col}>
            <div>
              <label style={css.label}>Phone number</label>
              <input style={css.input} placeholder="10-digit mobile" type="tel" maxLength={10}
                value={phone} onChange={e=>setPhone(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Password</label>
              <input style={css.input} placeholder="Your password" type="password"
                value={password} onChange={e=>setPassword(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>OTP</label>
              <OTPSender phone={phone} onSent={() => setOtpSent(true)}/>
              {otpSent && (
                <input style={{ ...css.input, marginTop:8 }} placeholder="Enter 6-digit OTP"
                  type="tel" maxLength={6} value={otp} onChange={e=>setOtp(e.target.value)}/>
              )}
            </div>
            <Alert msg={err}/>
            <button type="submit" style={{ ...css.btn, opacity: loading ? 0.6 : 1 }} disabled={loading}>
              {loading ? 'Signing in…' : 'Sign in'}
            </button>
            <div style={css.linkText}>
              No account? <span style={css.link} onClick={onGoRegister}>Sign up</span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

// ── REGISTER SCREEN ───────────────────────────────────────────────────────────
function RegisterScreen({ onLogin, onGoLogin }) {
  const [name,     setName]     = useState('');
  const [phone,    setPhone]    = useState('');
  const [password, setPassword] = useState('');
  const [confirm,  setConfirm]  = useState('');
  const [otp,      setOtp]      = useState('');
  const [err,      setErr]      = useState('');
  const [loading,  setLoading]  = useState(false);
  const [otpSent,  setOtpSent]  = useState(false);
  const [success,  setSuccess]  = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    if (!name || !phone || !password ) { setErr('All fields are required'); return; }
    if (password !== confirm) { setErr('Passwords do not match'); return; }
    if (password.length < 6)  { setErr('Password must be at least 6 characters'); return; }
    setLoading(true); setErr('');
    try {
      const { data } = await api.post('/auth/register/', { name, phone, password, otp });
      localStorage.setItem('token', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      setSuccess(data.user);
    } catch(e) {
      setErr(e.response?.data?.error || 'Registration failed');
    } finally { setLoading(false); }
  };

  if (success) {
    return (
      <div style={css.center}>
        <div style={{ ...css.authWrap, textAlign:'center' }}>
          <div style={css.card}>
            <div style={{ fontSize:48, marginBottom:16 }}>🎉</div>
            <div style={{ fontSize:22, fontWeight:800, color:G.text, marginBottom:8 }}>Account created!</div>
            <div style={{ fontSize:13, color:G.text3, marginBottom:24 }}>Your PrintShop ID</div>
            <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:16, padding:24, marginBottom:24 }}>
              <div style={{ fontSize:11, color:'#4ADE80', marginBottom:8 }}>Your ID</div>
              <div style={{ fontSize:56, fontWeight:900, color:G.green, letterSpacing:10 }}>{success.short_id}</div>
              <div style={{ fontSize:14, color:'#4ADE80', marginTop:8 }}>{success.name}</div>
            </div>
            <button style={css.btn} onClick={() => onLogin(success)}>Continue to app →</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={css.center}>
      <div style={css.authWrap}>
        <div style={css.brand}>
          <div style={css.brandIcon}>🖨️</div>
          <div style={css.brandName}>PrintShop</div>
        </div>
        <div style={css.card}>
          <div style={css.formTitle}>Create account</div>
          <form onSubmit={submit} style={css.col}>
            <div>
              <label style={css.label}>Full name</label>
              <input style={css.input} placeholder="Your name" value={name} onChange={e=>setName(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Phone number</label>
              <input style={css.input} placeholder="10-digit mobile" type="tel" maxLength={10}
                value={phone} onChange={e=>setPhone(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Password</label>
              <input style={css.input} placeholder="Min 6 characters" type="password"
                value={password} onChange={e=>setPassword(e.target.value)}/>
            </div>
            <div>
              <label style={css.label}>Confirm password</label>
              <input style={css.input} placeholder="Repeat password" type="password"
                value={confirm} onChange={e=>setConfirm(e.target.value)}/>
            </div>

            <Alert msg={err}/>
            <button type="submit" style={{ ...css.btn, opacity: loading?0.6:1 }} disabled={loading}>
              {loading ? 'Creating account…' : 'Create account'}
            </button>
            <div style={css.linkText}>
              Already have an account? <span style={css.link} onClick={onGoLogin}>Sign in</span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

