// ── NEW JOB SCREEN ─────────────────────────────────────────────────────────────
function NewJobScreen({ onNav }) {
  const [step,        setStep]        = useState(1); // 1=prefs, 2=confirm
  const [shops,       setShops]       = useState([]);
  const [shopId,      setShopId]      = useState('');
  const [fileName,    setFileName]    = useState('document.pdf');
  const [pages,       setPages]       = useState(1);
  const [colorMode,   setColorMode]   = useState('bw');
  const [paperSize,   setPaperSize]   = useState('A4');
  const [copies,      setCopies]      = useState(1);
  const [doubleSided, setDoubleSided] = useState(false);
  const [amount,      setAmount]      = useState(0);
  const [loading,     setLoading]     = useState(false);
  const [err,         setErr]         = useState('');

  useEffect(() => {
    api.get('/shops/nearby/').then(r => setShops(r.data.shops || [])).catch(()=>{});
  }, []);

  useEffect(() => {
    const RATES = { bw: {A4:1.5, A3:2.25, Letter:1.5}, color: {A4:7, A3:10.5, Letter:7} };
    const rate  = RATES[colorMode][paperSize];
    setAmount(+(rate * pages * copies * (doubleSided ? 0.8 : 1)).toFixed(2));
  }, [pages, colorMode, paperSize, copies, doubleSided]);

  const submit = async () => {
    if (!shopId) { setErr('Please select a shop'); return; }
    setLoading(true); setErr('');
    try {
      await api.post('/jobs/create/', { shop_id:shopId, file_name:fileName, pages, color_mode:colorMode, paper_size:paperSize, copies, double_sided:doubleSided });
      onNav('jobs');
    } catch(e) {
      setErr(e.response?.data?.error || 'Failed to create job');
    } finally { setLoading(false); }
  };

  const inp = (v, s, type='text', extra={}) => (
    <input style={css.input} type={type} value={v}
      onChange={e => s(type==='number' ? +e.target.value : e.target.value)} {...extra}/>
  );

  const chip = (val, cur, set, label) => (
    <button key={val} onClick={() => set(val)}
      style={{ padding:'8px 16px', borderRadius:8, border:`1.5px solid ${cur===val ? G.green : G.border2}`,
        background: cur===val ? G.greenBg : G.card2, color: cur===val ? G.green : G.text2,
        cursor:'pointer', fontWeight:600, fontSize:13 }}>
      {label}
    </button>
  );

  return (
    <div style={css.page}>
      <div style={{ ...css.row, marginBottom:20 }}>
        <button style={{ background:'none', border:'none', color:G.green, cursor:'pointer', fontSize:14, fontWeight:600 }} onClick={() => onNav('home')}>← Back</button>
      </div>
      <div style={css.pageTitle}>New print job</div>

      <div style={css.col}>
        {/* File name */}
        <div style={css.card}>
          <label style={css.label}>Document name</label>
          {inp(fileName, setFileName)}
        </div>

        {/* Shop */}
        <div style={css.card}>
          <label style={css.label}>Print shop</label>
          {shops.length === 0 ? (
            <div style={{ color:G.text3, fontSize:13 }}>No shops available nearby</div>
          ) : shops.map(s => (
            <div key={s.id} onClick={() => setShopId(s.id)}
              style={{ background: shopId===s.id ? G.greenBg : G.card2,
                border:`1.5px solid ${shopId===s.id ? G.green : G.border2}`,
                borderRadius:10, padding:12, cursor:'pointer', marginBottom:6 }}>
              <div style={{ fontWeight:700, color:G.text }}>{s.name}</div>
              <div style={{ fontSize:12, color:G.text3, marginTop:2 }}>{s.address}</div>
              {shopId===s.id && <div style={{ fontSize:12, color:G.green, marginTop:4 }}>✓ Selected</div>}
            </div>
          ))}
        </div>

        {/* Preferences */}
        <div style={css.card}>
          <label style={css.label}>Print preferences</label>
          <div style={{ marginBottom:12 }}>
            <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Color mode</div>
            <div style={css.row}>
              {chip('bw','bw'===colorMode ? 'bw' : colorMode, setColorMode, 'Black & White')}
              {chip('color','color'===colorMode ? 'color' : colorMode, setColorMode, 'Color')}
            </div>
          </div>
          <div style={{ marginBottom:12 }}>
            <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Paper size</div>
            <div style={css.row}>
              {['A4','A3','Letter'].map(s => chip(s, paperSize, setPaperSize, s))}
            </div>
          </div>
          <div style={{ ...css.row, marginBottom:12 }}>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Pages</div>
              <div style={css.row}>
                <button style={{ width:32, height:32, borderRadius:16, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:18 }}
                  onClick={() => setPages(p => Math.max(1,p-1))}>−</button>
                <span style={{ fontSize:18, fontWeight:700, color:G.text, minWidth:32, textAlign:'center' }}>{pages}</span>
                <button style={{ width:32, height:32, borderRadius:16, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:18 }}
                  onClick={() => setPages(p => p+1)}>+</button>
              </div>
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:12, color:G.text3, marginBottom:6 }}>Copies</div>
              <div style={css.row}>
                <button style={{ width:32, height:32, borderRadius:16, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:18 }}
                  onClick={() => setCopies(c => Math.max(1,c-1))}>−</button>
                <span style={{ fontSize:18, fontWeight:700, color:G.text, minWidth:32, textAlign:'center' }}>{copies}</span>
                <button style={{ width:32, height:32, borderRadius:16, background:G.card2, border:`1px solid ${G.border2}`, color:G.text, cursor:'pointer', fontSize:18 }}
                  onClick={() => setCopies(c => c+1)}>+</button>
              </div>
            </div>
          </div>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', background:G.card2, padding:12, borderRadius:10 }}>
            <div>
              <div style={{ fontWeight:600, color:G.text, fontSize:14 }}>Double-sided</div>
              <div style={{ fontSize:12, color:G.text3 }}>20% discount</div>
            </div>
            <div onClick={() => setDoubleSided(d => !d)}
              style={{ width:44, height:24, borderRadius:12, background: doubleSided ? G.greenDark : G.card2,
                border:`1px solid ${doubleSided ? G.green : G.border2}`, position:'relative', cursor:'pointer', transition:'background 0.2s' }}>
              <div style={{ position:'absolute', top:2, left: doubleSided ? 20 : 2, width:20, height:20,
                borderRadius:10, background:'#fff', transition:'left 0.2s' }}/>
            </div>
          </div>
        </div>

        {/* Cost */}
        <div style={{ background:G.greenBg, border:`1px solid ${G.greenBdr}`, borderRadius:14, padding:16, textAlign:'center' }}>
          <div style={{ fontSize:12, color:'#4ADE80', marginBottom:4 }}>Estimated total</div>
          <div style={{ fontSize:36, fontWeight:900, color:G.green }}>₹ {amount}</div>
        </div>

        <Alert msg={err}/>
        <button style={{ ...css.btn, opacity: loading||!shopId ? 0.5 : 1 }}
          onClick={submit} disabled={loading || !shopId}>
          {loading ? 'Creating…' : 'Create job →'}
        </button>
      </div>
    </div>
  );
}

